public class Main {
    static int subtotal(int harga, int jumlah) {
        return harga * jumlah;
    }

    public static void main(String[] args) {
        String[] barang = {"Kopi", "Teh", "Roti"};
        int[] harga = {5000, 4000, 7000};
        int[] jumlah = {2, 1, 3};
        int total = 0;
        for (int i = 0; i < barang.length; i++) {
            int sub = subtotal(harga[i], jumlah[i]);
            System.out.println(barang[i] + " x" + jumlah[i] + " = " + sub);
            total += sub;
        }
        System.out.println("Total: " + total);
    }
}

public class Main {
    static int subtotal(int harga, int jumlah) {
        return harga * jumlah;
    }


    static int diskon(int total) {
        if (total >= 30000) {
            return total * 10 / 100;
        }
        return 0;
    }

    public static void main(String[] args) {
        String[] barang = {"Kopi", "Teh", "Roti"};
        int[] harga = {5000, 4000, 7000};
        int[] jumlah = {2, 1, 3};
        int total = 0;
        for (int i = 0; i < barang.length; i++) {
            int sub = subtotal(harga[i], jumlah[i]);
            System.out.println(barang[i] + " x" + jumlah[i] + " = " + sub);
            total += sub;
        }
        System.out.println("Total: " + total);

        int potongan = diskon(total);
        System.out.println("Diskon: " + potongan);
        System.out.println("Bayar: " + (total - potongan));
    }
}

